import math

def _size(p, rule):
    if rule == "threshold":
        return 1.0 if p > 0.5 else (-1.0 if p < 0.5 else 0.0)
    m = math.erf((p - 0.5) / math.sqrt(p * (1 - p)) / math.sqrt(2))
    if rule == "afml":
        return m
    if rule == "afml_step":
        return round(m / 0.1) * 0.1
    if rule == "half_kelly":
        return 0.5 * (2 * p - 1)
    raise ValueError(rule)

def simulate(probs, returns, rule, cost_bp):
    pos = [_size(p, rule) for p in probs]
    net, prev = [], 0.0
    for x, r in zip(pos, returns):
        net.append(x * r - cost_bp / 10000 * abs(x - prev))
        prev = x
    m = sum(net) / len(net)
    sd = math.sqrt(sum((v - m) ** 2 for v in net) / (len(net) - 1))
    sharpe = round(m / sd * math.sqrt(252), 3) if sd > 0 else 0.0
    turn = sum(abs(pos[t] - pos[t - 1]) for t in range(1, len(pos))) / (len(pos) - 1)
    return (sharpe, round(turn, 4))

