import math
import numpy as np
from statistics import NormalDist

def make_prices(seed, n=600, phi=0.97, s_mu=0.0015, s_eps=0.01):
    """n + 1 closes from 100. Daily log return = slow drift mu_t (AR(1)) + noise."""
    rng = np.random.default_rng(seed)
    mu, r = 0.0, np.empty(n)
    k = s_mu * math.sqrt(1 - phi * phi)
    for t in range(n):
        mu = phi * mu + k * rng.standard_normal()
        r[t] = mu + s_eps * rng.standard_normal()
    return 100 * np.exp(np.concatenate([[0.0], np.cumsum(r)]))

def tb_label(prices, t, width, h):
    """Triple barrier from day t: 1 if the upper barrier is touched first,
    0 if the lower one is; at the time limit, 1 if the price ended higher."""
    p0 = prices[t]
    for d in range(1, h + 1):
        if prices[t + d] >= p0 * (1 + width):
            return 1
        if prices[t + d] <= p0 * (1 - width):
            return 0
    return int(prices[t + h] > p0)

def features(prices):
    """Row t, known at the close of day t (t >= 20): 5- and 20-day log returns,
    and 5-day over 20-day volatility of daily log returns."""
    r = np.diff(np.log(prices))
    X = np.full((len(prices), 3), np.nan)
    for t in range(20, len(prices)):
        w = r[t - 20:t]                      # the 20 returns ending at close t
        X[t] = [w[-5:].sum(), w.sum(), w[-5:].std() / w.std()]
    return X

def bet_size(p):
    z = (p - 0.5) / math.sqrt(p * (1 - p))
    return 2 * NormalDist().cdf(z) - 1

def sharpe(x):
    x = np.asarray(x)
    return float(x.mean() / x.std(ddof=1) * math.sqrt(252)) if x.std() > 0 else 0.0

def dsr(sr_ann, n, skew, kurt, n_trials):
    """Deflated Sharpe ratio, noise variance of a trial's daily Sharpe 1/(n - 1)."""
    sr = sr_ann / math.sqrt(252)
    g, nd = 0.5772156649015329, NormalDist()
    emax = 0.0 if n_trials <= 1 else math.sqrt(1 / (n - 1)) * (
        (1 - g) * nd.inv_cdf(1 - 1 / n_trials) + g * nd.inv_cdf(1 - 1 / (n_trials * math.e)))
    se = math.sqrt((1 - skew * sr + (kurt - 1) / 4 * sr ** 2) / (n - 1))
    return nd.cdf((sr - emax) / se)

